3	import { auth } from '@/lib/auth';
4	import { AuthError } from '@/lib/errors';
5	import type { AuthRole, AuthUserSummary } from '@/types/AuthUser';
6	
7	const MOCK_AUTH_COOKIE = 'mock-auth-state';
8	const MOCK_AUTH_USER_COOKIE = 'mock-auth-user';
9	
10	const mockUserDefaults = {
11	    user: {
12	        name: 'Test User',
13	        email: 'testuser@example.com',
14	        playerId: 1,
15	        role: 'user' as const,
16	    },
17	    admin: {
18	        name: 'Test Admin',
19	        email: 'testadmin@example.com',
20	        playerId: 2,
21	        role: 'admin' as const,
22	    },
23	};
24	
25	const parseCookieHeader = (
26	    cookieHeader: string | null,
27	): Record<string, string> => {
28	    if (!cookieHeader) return {};
29	
30	    return cookieHeader
31	        .split(';')
32	        .reduce<Record<string, string>>((acc, cookie) => {
33	            const trimmed = cookie.trim();
34	            if (!trimmed) return acc;
35	            const [name, ...rest] = trimmed.split('=');
36	            if (!name) return acc;
37	            acc[name] = decodeURIComponent(rest.join('='));
38	            return acc;
39	        }, {});
40	};
41	
42	const getMockAuthUserFromCookie = (
43	    cookieHeader: string | null,
44	): Partial<AuthUserSummary> | null => {
45	    const cookies = parseCookieHeader(cookieHeader);
46	    const rawValue = cookies[MOCK_AUTH_USER_COOKIE];
47	    if (!rawValue) return null;
48	
49	    try {
50	        const parsed = JSON.parse(rawValue) as Partial<AuthUserSummary> | null;
51	        return parsed ?? null;
52	    } catch {
53	        return null;
54	    }
55	};
56	
57	/**
58	 * Returns `true` when mock authentication is permitted.
59	 *
60	 * Mock auth is disabled in production to prevent cookie-based privilege
61	 * escalation. It is available when:
62	 *  - `NODE_ENV` is `'development'` or `'test'`, OR
63	 *  - `PLAYWRIGHT_TEST=true` is set (allows `next start` in production-build
64	 *    mode to honour mock-auth cookies during CI Playwright runs).
65	 */
66	export function isMockAuthEnabled(): boolean {
67	    return (
68	        process.env.NODE_ENV === 'development' ||
69	        process.env.NODE_ENV === 'test' ||
70	        process.env.PLAYWRIGHT_TEST === 'true'
71	    );
72	}
73	
74	/**
75	 * Reads the mock auth role from the request cookies.
76	 *
77	 * Always returns `'none'` in production to prevent cookie-based privilege
78	 * escalation. In development and test environments, reads the role from
79	 * `MOCK_AUTH_COOKIE`.
80	 *
81	 * @returns The mock role stored in `MOCK_AUTH_COOKIE`, or `'none'` when
82	 * absent, invalid, or in production.
83	 */
84	export async function getMockAuthState(): Promise<AuthRole> {
85	    if (!isMockAuthEnabled()) {
86	        return 'none';
87	    }
88	
89	    const cookieHeader = (await headers()).get('cookie');
90	    const cookies = parseCookieHeader(cookieHeader);
91	    const value = cookies[MOCK_AUTH_COOKIE];
92	    return value === 'admin' || value === 'user' ? value : 'none';
93	}
94	
