167	export async function getCurrentUser(): Promise<AuthUserSummary | null> {
168	    const mockUser = await getMockUser();
169	    if (mockUser) {
170	        return mockUser;
171	    }
172	
173	    const session = (await auth.api.getSession({
174	        headers: await headers(),
175	    })) as {
176	        session?: {
177	            impersonatedBy?: string | null;
178	        } | null;
179	        user?: {
180	            name?: string | null;
181	            email?: string | null;
182	            playerId?: number | null;
183	            role?: string | null;
184	        } | null;
185	    } | null;
186	
187	    if (!session?.user) {
188	        return null;
189	    }
190	
191	    return {
192	        name: session.user.name ?? null,
193	        email: session.user.email ?? null,
194	        playerId: session.user.playerId ?? 0,
195	        role: session.user.role === 'admin' ? 'admin' : 'user',
196	        impersonatedBy: session.session?.impersonatedBy ?? null,
197	    };
