200	/**
201	 * Retrieves the role of the currently authenticated user.
202	 *
203	 * @returns A promise that resolves to one of the following roles:
204	 * - `'none'`: If there is no active session or the session data is null.
205	 * - `'user'`: If the user is authenticated but does not have an admin role.
206	 * - `'admin'`: If the user is authenticated and has an admin role.
207	 *
208	 * The function uses `auth.api` to fetch the current session and determines
209	 * the user's role based on the session data.
210	 */
211	export async function getUserRole(): Promise<AuthRole> {
212	    const mockState = await getMockAuthState();
213	    if (mockState !== 'none') {
214	        return mockState;
215	    }
216	
217	    const session = (await auth.api.getSession({
218	        headers: await headers(),
219	    })) as { user?: { role?: string | null } | null } | null;
220	
221	    if (session?.user?.role === 'admin') {
222	        return 'admin';
223	    }
224	    if (session?.user) {
225	        return 'user';
226	    }
227	    return 'none';
228	}
