230	/**
231	 * Asserts that the current user holds the `admin` role.
232	 *
233	 * Throws an {@link AuthError} with an appropriate message when the caller is
234	 * unauthenticated (`'none'`) or lacks admin privileges (`'user'`).
235	 *
236	 * @throws {AuthError} When the user is not an admin.
237	 */
238	export async function requireAdmin(): Promise<void> {
239	    const role = await getUserRole();
240	
241	    switch (role) {
242	        case 'admin':
243	            return;
244	        case 'user':
245	            throw new AuthError('Forbidden: admin access required.');
246	        case 'none':
247	        default:
248	            throw new AuthError('Unauthorised: you must be logged in.');
249	    }
250	}
251	
252	/**
253	 * Asserts that the current user is authenticated (any role).
254	 *
255	 * Throws an {@link AuthError} when the caller is unauthenticated.
256	 *
257	 * @throws {AuthError} When no user session exists.
258	 */
259	export async function requireUser(): Promise<void> {
260	    const role = await getUserRole();
261	
262	    if (role === 'none') {
263	        throw new AuthError('Unauthorised: you must be logged in.');
264	    }
265	}
