2	 * Decodes a URI-encoded string, falling back to the original value unchanged
3	 * if it contains malformed percent-encoding (which makes decodeURIComponent
4	 * throw a URIError) rather than letting that crash the caller.
5	 */
6	export function safeDecodeURIComponent(value: string): string {
7	    try {
8	        return decodeURIComponent(value);
9	    } catch {
10	        return value;
11	    }
