14	/**
15	 * Returns the normalized public base URL for the application.
16	 *
17	 * Checks SITE_URL first (server-only, read at runtime — not baked in at build
18	 * time), then NEXT_PUBLIC_SITE_URL (inlined at build time for both client and
19	 * server bundles), then BETTER_AUTH_URL, then the current browser origin, and
20	 * finally falls back to http://localhost:3000.
21	 */
22	export function getPublicBaseUrl(): string {
23	    const runtimeUrl = process.env.SITE_URL?.trim();
24	    if (runtimeUrl) {
25	        return runtimeUrl.replace(/\/+$/, '');
26	    }
27	
28	    const envUrl = process.env.NEXT_PUBLIC_SITE_URL?.trim();
29	    if (envUrl) {
30	        return envUrl.replace(/\/+$/, '');
31	    }
32	
33	    const serverUrl = process.env.BETTER_AUTH_URL?.trim();
34	    if (serverUrl) {
35	        return serverUrl.replace(/\/+$/, '');
36	    }
37	
38	    if (typeof window !== 'undefined' && window.location?.origin) {
39	        return window.location.origin;
40	    }
41	
42	    return 'http://localhost:3000';
43	}
44	
45	/**
46	 * Returns the origins Better Auth should trust for CORS/CSRF checks, in
47	 * addition to baseURL (which Better Auth trusts implicitly).
48	 *
49	 * Reads TRUSTED_ORIGINS (comma-separated, server-only, read at runtime — not
50	 * baked in at build time), so the allow-list can change per deployment (e.g.
51	 * widened while a new domain shadows the old one) without rebuilding the
52	 * image. Defaults to localhost:3000 only, for local testing, when unset —
53	 * real deployments are expected to set TRUSTED_ORIGINS explicitly.
54	 */
55	export function getTrustedOrigins(): string[] {
56	    const configured = process.env.TRUSTED_ORIGINS?.split(',')
57	        .map((origin) => origin.trim())
58	        .filter(Boolean);
59	
60	    return configured && configured.length > 0
61	        ? configured
62	        : ['http://localhost:3000'];
63	}
