'use server';

import { revalidatePath } from 'next/cache';

import { requireAdmin } from '@/lib/auth.server';
import { coreListUsersAction, coreSetAdminRoleAction } from '@/lib/core/auth';
import { broadcast } from '@/lib/events';
import { FootyChannel } from '@/types/FootyChannel';

/**
 * Lists auth users, optionally filtered by email.
 *
 * @param email - Optional email filter.
 * @param limit - Maximum number of users to fetch when `email` is absent.
 * Defaults to 10.
 * @throws {AuthError} When the user is not an admin.
 */
export async function listUsersAction(email?: string, limit?: number) {
    await requireAdmin();

    return await coreListUsersAction(email, limit);
}

/**
 * Grants or revokes admin role for a user.
 *
 * @param userId - The target user ID.
 * @param isAdmin - Whether to grant (`true`) or revoke (`false`) admin.
 * @throws {AuthError} When the user is not an admin.
 */
export async function setAdminRoleAction(userId: string, isAdmin: boolean) {
    await requireAdmin();

    await coreSetAdminRoleAction(userId, isAdmin);

    revalidatePath('/footy/admin/users');
    revalidatePath('/footy/admin/user', 'layout');
    broadcast(FootyChannel.Users);
}

interface RequestPasswordResetInput {
    email: string;
    redirectTo: string;
}

type SpyFactory = <A extends unknown[], R>(
    implementation?: (...args: A) => R,
) => ((...args: A) => R) & { mock?: unknown };

const getSpyFactory = (): SpyFactory => {
    if (typeof globalThis !== 'undefined') {
        const storybookFn = (globalThis as Record<string, unknown>)
            .__STORYBOOK_FN__;
        if (typeof storybookFn === 'function') {
            return storybookFn as SpyFactory;
        }

        const vitestFn = (globalThis as { vi?: { fn?: SpyFactory } }).vi?.fn;
        if (vitestFn) {
            return vitestFn;
        }
    }

    return <A extends unknown[], R>(implementation?: (...args: A) => R) => {
        const fn = ((...args: A): R => {
            if (implementation) {
                return implementation(...args);
            }
            // No-op spy when no implementation is provided
            return undefined as R;
        }) as ((...args: A) => R) & { mock?: unknown };
        return fn;
    };
};

const spy = getSpyFactory();

/**
 * Mocked Better Auth client for Storybook and Vitest tests.
 */
export const authClient = {
    requestPasswordReset: spy((_input: RequestPasswordResetInput) =>
        Promise.resolve({ status: true }),
    ),
    resetPassword: spy((_input: { newPassword: string; token?: string }) =>
        Promise.resolve({ status: true }),
    ),
    changePassword: spy(
        (_input: {
            currentPassword: string;
            newPassword: string;
            revokeOtherSessions?: boolean;
        }) => Promise.resolve({ status: true }),
    ),
    signIn: {
        email: spy((_args: { email: string; password: string }) =>
            Promise.resolve({}),
        ),
        social: spy((_args: { provider: string; callbackURL: string }) =>
            Promise.resolve({}),
        ),
    },
    signInWithEmail: spy((_email: string, _password: string) =>
        Promise.resolve({}),
    ),
    signUp: {
        email: spy((_args: { name: string; email: string; password: string }) =>
            Promise.resolve({}),
        ),
    },
    useSession: spy(() => ({
        data: null,
        isPending: false,
        isRefetching: false,
        error: null,
        refetch: spy(),
    })),
};

/**
 * Mock social sign-in helper for Google.
 */
export const signInWithGoogle = spy((callbackURL: string) =>
    authClient.signIn.social({ provider: 'google', callbackURL }),
);

/**
 * Mock social sign-in helper for Microsoft.
 */
export const signInWithMicrosoft = spy((callbackURL: string) =>
    authClient.signIn.social({ provider: 'microsoft', callbackURL }),
