import { z } from 'zod';

export type AuthRole = 'none' | 'user' | 'admin';

export interface AuthUserSummary {
    name: string | null;
    email: string | null;
    playerId: number;
    role: AuthRole;
    impersonatedBy?: string | null;
}

/**
 * Runtime schema that coerces an untrusted auth-user-shaped object — the user
 * Better Auth hands to lifecycle hooks, or a decoded session — into an
 * {@link AuthUserSummary}.
 *
 * Missing/blank `name` and `email` become `null`, a missing `playerId` becomes
 * `0`, and any role other than `'admin'` collapses to `'user'` (mirroring the
 * session mapping in `getCurrentUser`). Unknown fields are dropped. A value
 * that is not an object at all fails to parse, so callers get a thrown error
 * rather than a silently malformed summary.
 */
export const authUserSummarySchema: z.ZodType<
    AuthUserSummary,
    z.ZodTypeDef,
    unknown
> = z
    .object({
        name: z.string().nullish(),
        email: z.string().nullish(),
        playerId: z.number().int().nullish(),
        role: z.string().nullish(),
        impersonatedBy: z.string().nullish(),
    })
    .transform((user) => ({
        name: user.name ?? null,
        email: user.email ?? null,
        playerId: user.playerId ?? 0,
        role: user.role === 'admin' ? ('admin' as const) : ('user' as const),
        impersonatedBy: user.impersonatedBy ?? null,
    }));

/**
 * Maps an untrusted auth-user-shaped value to an {@link AuthUserSummary} using
 * {@link authUserSummarySchema}.
 *
 * @throws {z.ZodError} When `user` is not an object or a field has the wrong
 * type (e.g. a non-numeric `playerId`).
 */
export function toAuthUserSummary(user: unknown): AuthUserSummary {
    return authUserSummarySchema.parse(user);
}

